using Nafadh_Backend.DTOs;
using Nafadh_Backend.Repositories;

namespace Nafadh_Backend.Services
{
    // Read-facing service backing BadgeController — the fixed catalog and a
    // trainee's earned badges. Granting itself is handled by
    // IBadgeEvaluationService, never triggered from this service or its controller.
    public class BadgeService : IBadgeService
    {
        private readonly IBadgeRepository _repository;

        public BadgeService(IBadgeRepository repository)
        {
            _repository = repository;
        }

        public async Task<List<BadgeDTO>> GetAllBadgesAsync()
        {
            var badges = await _repository.GetAllBadgesAsync();
            return badges.Select(MapToDTO).ToList();
        }

        public async Task<List<TraineeBadgeDTO>> GetTraineeBadgesAsync(int traineeId)
        {
            var earned = await _repository.GetTraineeBadgesAsync(traineeId);
            return earned.Select(tb => new TraineeBadgeDTO
            {
                TraineeBadgeId = tb.TraineeBadgeId,
                TraineeId = tb.TraineeId,
                BadgeId = tb.BadgeId,
                EarnedAt = tb.EarnedAt,
                Badge = tb.Badge != null ? MapToDTO(tb.Badge) : null
            }).ToList();
        }

        private static BadgeDTO MapToDTO(Models.NFD_Badge b) => new BadgeDTO
        {
            BadgeId = b.BadgeId,
            Name = b.Name,
            Description = b.Description,
            Icon = b.Icon,
            ConditionType = b.ConditionType,
            ConditionValue = b.ConditionValue
        };
    }
}
